"""Write src/confusables.ts: Unicode's confusables, each character's prototype, from confusables.txt.

The data is UTS #39's (Unicode Security Mechanisms), Unicode License V3 (see NOTICE). The table
keeps every entry, so it doesn't depend on this Python's `unicodedata`. Download the version wanted
and run it from the repository root, then commit both files:

    curl -O https://www.unicode.org/Public/18.0.0/security/confusables.txt
    python3 -I tests/fixtures/confusables.py confusables.txt
"""

import pathlib
import re
import sys

DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def base36(number: int) -> str:
    return (base36(number // 36) if number >= 36 else "") + DIGITS[number % 36]


def read(path: str) -> tuple[str, dict[int, list[int]]]:
    text = pathlib.Path(path).read_text(encoding="utf-8-sig")
    version = re.search(r"^# Version: (\S+)$", text, re.M)
    if version is None:
        sys.exit(f"{path} names no version")
    prototypes: dict[int, list[int]] = {}
    for line in text.splitlines():
        fields = line.split("#", 1)[0].strip()
        if not fields:
            continue
        source, target, _ = (field.strip() for field in fields.split(";"))
        prototypes[int(source, 16)] = [int(code, 16) for code in target.split()]
    return version.group(1), prototypes


def main() -> None:
    if len(sys.argv) != 2:
        sys.exit("usage: python3 -I tests/fixtures/confusables.py confusables.txt")
    version, prototypes = read(sys.argv[1])
    entries = []
    last = 0
    for source in sorted(prototypes):
        target = ".".join(base36(code) for code in prototypes[source])
        entries.append(f"{base36(source - last)}:{target}")
        last = source
    rows, row = [], ""
    for entry in entries:
        if len(row) + len(entry) + 1 > 98:
            rows.append(row)
            row = ""
        row = f"{row} {entry}" if row else entry
    rows.append(row)
    lines = "\n".join(f"  {each}" for each in rows)
    text = f"""/**
 * Unicode's confusables (UTS #39, Unicode Security Mechanisms) version {version}: each character's
 * prototype, the characters it looks like. Unicode License V3; see NOTICE.
 *
 * Generated by `tests/fixtures/confusables.py` from Unicode's `confusables.txt`: run it again
 * rather than edit this file.
 *
 * Knows about: nothing else.
 */

/** The version of Unicode's security data `CONFUSABLES` is from. */
export const CONFUSABLES_VERSION = "{version}";

/**
 * Each character and its prototype, in code point order: `<source>:<target>`, where the source is
 * base 36 and counts from the previous entry's, and the target is its code points in base 36,
 * joined by `.`.
 */
export const CONFUSABLES = `
{lines}
`;
"""
    root = pathlib.Path(__file__).resolve().parents[2]
    root.joinpath("src", "confusables.ts").write_text(text)


if __name__ == "__main__":
    main()
